WITH f AS (SELECT customer_id,MIN(ordered_on) first_on FROM #ShopOrders WHERE status=N'paid' GROUP BY customer_id)
SELECT DATEFROMPARTS(YEAR(first_on),MONTH(first_on),1) cohort_month,COUNT(*) customer_count
FROM f GROUP BY DATEFROMPARTS(YEAR(first_on),MONTH(first_on),1);

SELECT l.product_id,CAST(SUM(l.qty*l.unit_price)/SUM(CAST(l.qty AS decimal(18,2))) AS decimal(18,2)) weighted_price
FROM #ShopLines l JOIN #ShopOrders o ON o.order_id=l.order_id
WHERE o.status=N'paid' GROUP BY l.product_id;

SELECT p.product_id FROM #ShopProducts p WHERE NOT EXISTS
 (SELECT 1 FROM #ShopLines l JOIN #ShopOrders o ON o.order_id=l.order_id
 WHERE l.product_id=p.product_id AND o.status=N'paid');

WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY machine_id ORDER BY observed_at,reading_id) rn FROM #OpsReadings),
p AS (SELECT *,MAX(CASE WHEN reading IS NOT NULL THEN rn END) OVER(PARTITION BY machine_id ORDER BY rn ROWS UNBOUNDED PRECEDING) last_rn FROM r)
SELECT p.reading_id,CAST(v.reading AS decimal(10,2)) effective_reading FROM p LEFT JOIN r v ON v.machine_id=p.machine_id AND v.rn=p.last_rn;
